import{_ as i,a0 as m,w as p,s as l,ao as e,I as n,x as a,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux vmstat 命令 - 報告虛擬內存統計的工具 | LCTT x X-CMD","titleTemplate":false,"description":"Linux vmstat 命令 - 報告虛擬內存統計的工具 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux vmstat 命令 - 報告虛擬內存統計的工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux vmstat 命令 - 報告虛擬內存統計的工具 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Linux vmstat Command - Tool to Report Virtual Memory Statistics","title":"Linux vmstat 命令 - 報告虛擬內存統計的工具","tag":"201401","desc":""},"relativePath":"201401/Linux vmstat Command - Tool to Report Virtual Memory Statistics.md","filePath":"[post].md"}'),d={name:"201401/Linux vmstat Command - Tool to Report Virtual Memory Statistics.md"};function g(h,t,u,v,x,c){const s=m("Link");return p(),l("div",null,[t[14]||(t[14]=e('<h1 id="linux-vmstat-命令-報告虛擬內存統計的工具" tabindex="-1">Linux vmstat 命令 - 報告虛擬內存統計的工具 <a class="header-anchor" href="#linux-vmstat-命令-報告虛擬內存統計的工具" aria-label="Permalink to “Linux vmstat 命令 - 報告虛擬內存統計的工具”">​</a></h1><p>眾所周知，計算機必須有稱之為RAM(隨機訪問內存)的存儲器使得計算機工作。RAM指的是插在計算機主板上的物理存儲。這裏的RAM被用於加載像瀏覽器、文字處理器這類的程序，實際上，你使用的程序都運行在內存上。</p><p>讓我們假設你有2GB的內存。當你在運行操作系統時，你的可用內存可能只有1.5GB。接着你使用了大量的程序。當內存使用滿之後，你可能再也無法加載更多的程序。淺顯地説，計算機可能會説:&quot;抱歉，你不能在運行更多的程序了，如果你還要運行其他的程序請先關閉一些程序。&quot;</p><p>為了解決這個問題，包括Linux在內的各種操作系統使用了一個稱之為虛擬內存的方法。這個方法會搜索最近不在使用的程序的內存區域，接着將它們拷貝到計算機硬盤上。這會騰出一些剩餘內存空間給你有機會運行更多的程序。</p><p>為了監視虛擬內存的活動，我們使用<strong>vmstat</strong>工具。</p><h3 id="什麼是-vmstat" tabindex="-1">什麼是 vmstat <a class="header-anchor" href="#什麼是-vmstat" aria-label="Permalink to “什麼是 vmstat”">​</a></h3><p>vmstat是一個提供報告虛擬內存統計的工具。它包括了系統內存、交換和實時處理器利用率。</p><h3 id="如何運行-vmstat" tabindex="-1">如何運行 vmstat <a class="header-anchor" href="#如何運行-vmstat" aria-label="Permalink to “如何運行 vmstat”">​</a></h3>',8)),n("p",null,[t[1]||(t[1]=a("和",-1)),o(s,{href:"http://linoxide.com/linux-command/linux-mpstat-command/"},{default:r(()=>[...t[0]||(t[0]=[a("mpstat",-1)])]),_:1}),t[2]||(t[2]=a("一樣，vmstat包含在sysstat包中。如果你還沒有，請安裝sysstat包。",-1))]),t[15]||(t[15]=e(`<p>為了運行vmstat，只需在控制台輸入vmstat。不帶參數運行vmstat會顯示vmstat的默認結果。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_default.png" alt=""></p><p>讓我們看下如何瞭解vmstat提供的信息：</p><h4 id="procs" tabindex="-1">Procs <a class="header-anchor" href="#procs" aria-label="Permalink to “Procs”">​</a></h4><p>procs有 <strong>r</strong>列和<strong>b</strong>列。<strong>r</strong>列代表等待訪問CPU進程的數量。而b列意味着睡眠進程的數量。在這些列的下面，是它們的值。從上面的截圖中，我門有2個進程正在等待訪問CPU，0個睡眠進程。</p><h4 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to “Memory”">​</a></h4><p>memory有<strong>swpd、 free、 buff</strong> 和 <strong>cache</strong> 這些列。這些信息和命令<strong>free -m</strong>相同。<strong>swpd列</strong>顯示了有多少內存已經被交換到了交換文件或者磁盤。<strong>free列</strong>顯示了未分配的可用內存。<strong>buff列</strong>顯示了使用中的內存。<strong>cache列</strong>顯示了有多少內存可以被交換到交換文件或者磁盤上如果一些應用需要他們。</p><h4 id="swap" tabindex="-1">Swap <a class="header-anchor" href="#swap" aria-label="Permalink to “Swap”">​</a></h4><p>swap顯示了從交換系統上發送或取回了多少內存。<strong>si</strong>列告訴我們每秒有多少內存被<strong>從swap移到真實內存</strong>中（In）。<strong>so</strong>列告訴我們每秒有多少內存被<strong>從真實內存移到swap</strong>中（Out）。</p><h4 id="i-o" tabindex="-1">I/O <a class="header-anchor" href="#i-o" aria-label="Permalink to “I/O”">​</a></h4><p><strong>io</strong>依據塊的讀寫顯示了每秒輸入輸出的活動。<strong>bi</strong>列告訴我們收到的塊數量，<strong>bo</strong>列告訴我們發送的塊數量。</p><h4 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to “System”">​</a></h4><p>system顯示了每秒的系統操作數量。<strong>in</strong>列顯示了系統每秒被中斷的數量。<strong>cs</strong>列顯示了系統為了處理所以任務而上下文切換的數量。</p><h4 id="cpu" tabindex="-1">CPU <a class="header-anchor" href="#cpu" aria-label="Permalink to “CPU”">​</a></h4><p>CPU告訴了我們CPU資源的使用情況。<strong>us列</strong>顯示了處理器在非內核程序消耗的時間。<strong>sy列</strong>顯示了處理器在內核相關任務上消耗的時間。<strong>id列</strong>顯示了處理器的空閒時間。<strong>wa列</strong>顯示了處理器在等待IO操作完成以繼續處理任務上的時間。</p><h3 id="按間隔時間運行vmstat" tabindex="-1">按間隔時間運行vmstat <a class="header-anchor" href="#按間隔時間運行vmstat" aria-label="Permalink to “按間隔時間運行vmstat”">​</a></h3><p>作為一個統計工具，使用vmstat最好的方法是使用<strong>間隔時間</strong>。你可以間斷地捕捉系統狀態。讓我假設以5秒的間隔運行vmstat。只需要在你的控制台中輸入<strong>vmstat 5</strong>就行。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_delay_5.png" alt=""></p><p>命令將會每5秒運行一次，<strong>直到</strong>你按下Ctrl-C來終止它。你也可以使用第二個參數來控制vmstat運行的次數。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_count_7.png" alt=""></p><p>上面的命令會<strong>以5秒的間隔運行7次vmstat</strong>。</p><h3 id="顯示活躍和非活躍內存" tabindex="-1">顯示活躍和非活躍內存 <a class="header-anchor" href="#顯示活躍和非活躍內存" aria-label="Permalink to “顯示活躍和非活躍內存”">​</a></h3><p>要這麼做，你可以在vmstat後加入<strong>-a</strong>選項。這是個示例。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_a.png" alt=""></p><h3 id="顯示磁盤統計數據總結" tabindex="-1">顯示磁盤統計數據總結 <a class="header-anchor" href="#顯示磁盤統計數據總結" aria-label="Permalink to “顯示磁盤統計數據總結”">​</a></h3><p>如果你想，vmstat也可以打印系統磁盤活動統計。使用<strong>-D</strong>選項就行。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_disk_sum.png" alt=""></p><h3 id="顯示單位" tabindex="-1">顯示單位 <a class="header-anchor" href="#顯示單位" aria-label="Permalink to “顯示單位”">​</a></h3><p>你可以選擇你想打印的顯示單位字符。在<strong>-S後跟上k (小寫，1000)、 K (大寫，1024)、 m (小寫，1000000)、 M (大寫，1048576)</strong> 字節. 如果你不想選擇單位，默認使用的是K (1024)。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_define_unit.png" alt=""></p><h3 id="顯示某個磁盤分區的詳細統計數據" tabindex="-1">顯示某個磁盤分區的詳細統計數據 <a class="header-anchor" href="#顯示某個磁盤分區的詳細統計數據" aria-label="Permalink to “顯示某個磁盤分區的詳細統計數據”">​</a></h3><p>要這麼做，你可以使用<strong>-p選項跟上設備名</strong>。這裏有個例子。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/vmstat_partition.png" alt=""></p><h3 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to “文件”">​</a></h3><p>vmstat實際上是使用這些文件獲取的數據。</p><pre><code>/proc/meminfo
/proc/stat
/proc/*/stat 
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>如果你感覺系統運行超出內存了，在你增加物理內存前，這個工具可以幫助你確定問題的根本原因。通常上，你可以在控制台中輸入<strong>man vmstat</strong>獲取更多的關於vmstat的詳細信息，這會為你顯示vmstat的手冊頁。</p><hr>`,39)),n("p",null,[t[4]||(t[4]=a("via: ",-1)),o(s,{href:"http://linoxide.com/linux-command/linux-vmstat-command-tool-report-virtual-memory-statistics/"},{default:r(()=>[...t[3]||(t[3]=[a("http://linoxide.com/linux-command/linux-vmstat-command-tool-report-virtual-memory-statistics/",-1)])]),_:1})]),n("p",null,[t[7]||(t[7]=a("譯者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:r(()=>[...t[5]||(t[5]=[a("geekpi",-1)])]),_:1}),t[8]||(t[8]=a(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:r(()=>[...t[6]||(t[6]=[a("wxy",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=a("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[9]||(t[9]=[a("LCTT",-1)])]),_:1}),t[12]||(t[12]=a(" 原創翻譯，",-1)),o(s,{href:"http://linux.cn/"},{default:r(()=>[...t[10]||(t[10]=[a("Linux中國",-1)])]),_:1}),t[13]||(t[13]=a(" 榮譽推出",-1))])])}const _=i(d,[["render",g]]);export{T as __pageData,_ as default};
